// 8-word lookup table: becomes logic (gates / LUTs)
module rom_case (
  input  logic [2:0] addr,
  output logic [7:0] data
);
  always_comb
    case (addr)
      3'd0: data = 8'h3C;
      3'd1: data = 8'h7E;
      3'd2: data = 8'hDB;
      3'd3: data = 8'hFF;
      3'd4: data = 8'hDB;
      3'd5: data = 8'h66;
      3'd6: data = 8'h3C;
      default: data = 8'h00;
    endcase
endmodule

module rom #(
  parameter int    DW    = 16,
  parameter int    DEPTH = 1024,
  parameter string INIT  = "rom.hex"     // one hex word per line
) (
  input  logic                     clk,
  input  logic [$clog2(DEPTH)-1:0] addr,
  output logic [DW-1:0]            data
);
  logic [DW-1:0] mem [DEPTH];
  initial $readmemh(INIT, mem);          // content at time 0
  always_ff @(posedge clk) data <= mem[addr];   // synchronous read
endmodule
